  },
  LanguageConfig_DailyChallengeExpAttenuationRulesTipsTitle_CN = {Text = "Règles"},
  LanguageConfig_DailyChallengeExpAttenuationRulesTips_CN = {
    Text = "·Lorsque le « Niveau du Gardien du Secret » ou le « Niveau moyen de l'équipe » est nettement supérieur au niveau recommandé du défi, l'expérience de plongée en eaux profondes obtenue est réduite."
