  LanguageConfig_ResurrectionCoinPurchaseTips_CN = {
    Text = "(Après l'échange, le Corps de Gnosis d'urgence sera immédiatement consommé et la Résurrection sera effectuée. En cas de retraite, le Corps de Gnosis d'urgence sera restitué. Le Corps de Gnosis d'urgence est limité à 3 achats par semaine. Utilisations restantes actuelles : {s1}/3)"
