  LanguageConfig_ResurrectionCoinSkillDescription_CN = {
    Text = "Après la mort, déclencher, après avoir utilisé le corps de gnose d'urgence, restaurez toute vie, aliemus, s-énergie, et immunisez tous les dégâts suivants du tour"
