  LanguageConfig_SchoolTowerRuleTxt_CN = {
    Text = "<Title:Royaume sans lumière>\n·Le Royaume sans lumière est une série de niveaux de difficulté élevée. En terminant les niveaux, vous pouvez obtenir des récompenses généreuses. De plus, en atteignant des étoiles de notation cumulées des niveaux, vous pouvez également recevoir des récompenses supplémentaires. \n\n<Title:Exigences d'enquête>\n·Les niveaux du Royaume sans lumière peuvent exiger d'utiliser des Éveilleurs d'un royaume spécifique et en quantité donnée pour mener l'enquête, le Gardien peut consulter les détails des niveaux et l'interface de configuration de l'équipe. \n\n<Title:Relique initiale>\n·Les niveaux du Royaume sans lumière contiennent des reliques uniques, qui ne sont actives que dans le niveau en cours. Utiliser efficacement les effets des reliques rendra l'enquête beaucoup plus efficace."
  },
  LanguageConfig_SchoolTowerTeamBuildFobiddenTips_CN = {
    Text = "Sélection non conforme aux exigences de l'équipe"
  },
  LanguageConfig_School_Activate_CN = {Text = "Activé"},
  LanguageConfig_School_Blood_Content_String_CN = {
    Text = "Au début de chaque tour, <CardKeyWord:Fusion d'Embryon> +20 (augmente avec la perte de PV, maximum 40). Lorsqu'elle atteint la limite, place 1 <CardKeyWord:« Embryon »> dans votre Main.\nL'« Exaltation » du Royaume de Chair consomme <CardKeyWord:« Embryon »> pour déclencher l'effet <CardKeyWord:Dévorer>. Après la première Dévoration de chaque tour, gagnez un Bouclier du personnage équivalent à 2 % des PV Max et une Force Temporaire équivalente à 1 % des PV Max. (Augmente avec la perte de PV, maximum 2 fois)"
  },
  LanguageConfig_School_Blood_Title_String_CN = {
    Text = "Sacrifice Écarlate"
  },
  LanguageConfig_School_Chaos_Content_String_CN = {
    Text = "·Les éveillés du royaume du Chaos peuvent dépasser les limites du royaume et composer avec d'autres éveillés de royaume. \n · Si un éveillé du Chaos est présent dans n'importe quelle équipe, il peut obtenir 100 % de résistance à la mort supplémentaire. \n · À la fin du tour et après avoir utilisé « Exaltation », <CardKeyWord:Fragment de clé> +50."
  },
  LanguageConfig_School_Chaos_Title_String_CN = {
    Text = "Phénomènes cosmiques"
  },
  LanguageConfig_School_Dimension_Content_String_CN = {
    Text = "·La première copie temporaire de la carte d'instruction jouée chaque tour entre dans <CardKeyWord:Espace Hyperspatial> et déclenche son effet de saut quantique. \n·Lorsque l'espace hyperspatial atteint sa limite, gagnez un tour ultra supplémentaire, pendant lequel vous ne piochez plus de cartes normalement, mais ajoutez les cartes de l'espace hyperspatial à votre main. Le tour ultra peut déclencher tous les effets de saut quantique."
  },
  LanguageConfig_School_Dimension_Title_String_CN = {
    Text = "Saut Dimensionnel"
  },
  LanguageConfig_School_Ocean_Content_String_CN = {
    Text = "·Au début de la bataille, générez 1 tentacule qui attaquera les ennemis de la ligne avant à la fin du tour. \n ·Chaque fois que vous libérez 1 explosion de folie, incitez 1 tentacule à attaquer à la fin du tour. \n ·Pour chaque 3 points de force, fournissez 1 point de dégâts de tentacule, chaque fois que la force diminue de 3 points, les dégâts de tentacule sont réduits de 1 point."
