  LanguageConfig_StorylineGuide_0_CN = {
    Text = "Vivre face à la mort."
  },
  LanguageConfig_StorylineGuide_10_CN = {
    Text = "Bien sûr, le chaos est la fin de tout. Mais il y a toujours des gens qui ne veulent pas abandonner la lutte, n'est-ce pas ?"
  },
  LanguageConfig_StorylineGuide_11_CN = {
    Text = "Ne pas regarder directement l'univers au-dessus de soi. Ne pas regarder directement l'abîme intérieur."
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "Manger est la seule vertu de ce monde."
  },
  LanguageConfig_StorylineGuide_13_CN = {
    Text = "Aucun réponse dans ce rêve sans fin. Ce rêve, il est temps de se réveiller."
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "Sur la scène du destin, les rôles que nous allons jouer, nous n'avons jamais eu le choix."
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "Ô Voyageurs, avancez doucement dans cette nuit enneigée. Au sommet des volontés éteintes, puissiez-vous être témoins de la fin d'un grand rêve."
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "Texte temporaire"
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "Texte temporaire"
  },
  LanguageConfig_StorylineGuide_18_CN = {
    Text = "Texte temporaire"
  },
  LanguageConfig_StorylineGuide_19_CN = {
    Text = "Texte temporaire"
  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "Entre dans le brouillard nocturne dangereux de Londinium, Gardien. Le chemin qui t'appartient commence ici."
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "Texte temporaire"
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "Artiste, fou, ascète, imbécile... cette ville est ton musée, les statues en cire se tiennent au début de l'histoire, attendant ta venue avec impatience."
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "Le vent et la neige de Rai méprisent le meurtre, elle t'attend, uniquement pour un échange. Elle t'apportera le secret que tu désires tant. Son prix est toujours cruel, toujours raisonnable."
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "Souviens-toi, combats pour les souvenirs, meurs pour les souvenirs. Les souvenirs sont notre évangile, notre épitaphe. À part les souvenirs, nous n'avons rien."
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "Avant la chute des étoiles, nous prions face à l'océan : que le doux murmure des vagues nous protège dans le rêve, que nous retournions dans les bras de notre terre natale, et que le long rêve ne s'éveille pas."
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "Chantez — l'ancien roi a de nouveau aperçu son trône. Le décret sacré apportera le royaume de Dieu à chaque fidèle dévoué."
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "Écouter, prier, appeler, se reproduire, obéir aux idéaux les plus nobles et aux désirs les plus humbles. Au nom de la mère, Il peut subsister dans le chaos et la peur."
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "La lampe éternelle est allumée, cette lumière sombre éclairera le chemin qui mène à ta fin."
  },
  LanguageConfig_StorylineGuide_9_CN = {
    Text = "Dis-lui, ta réponse."
  },
  LanguageConfig_StrongerTitle_CN = {
    Text = "Récupérez des matériaux via l'« Interlude d'Exercice » pour améliorer votre corps éveillé !"
  },
  LanguageConfig_StrongerWayTitle_CN = {
    Text = "Comment devenir plus fort"
  },
  LanguageConfig_StrongerWay_CN = {
    Text = "· Débloquez \"Opération d'enquête\" 1-2 : Normal pour accéder aux \"Ruines de dissolution\", qui offrent une grande quantité de matériaux de développement pour les éveillés. \n · Débloquez \"Opération d'enquête\" 3-10 : Normal pour accéder à \"Existence transcendante\", qui fournit une quantité substantielle de matériaux de mise à niveau des compétences des éveillés. \n · Débloquez \"Niveau d'enquête\" 15 pour accéder à la \"Deuxième roue de destin\", permettant d'équiper une deuxième roue pour augmenter la puissance de combat. \n · Débloquez \"Niveau d'enquête\" 25 pour accéder au \"Pacte interdit\", qui fournit un grand nombre de pactes pour améliorer les capacités des éveillés."
  },
