  LanguageConfig_TrinketAutoRefineStopByMaxTimeLimit_CN = {
    Text = "100 Transcriptions terminées."
  },
  LanguageConfig_TrinketAutoRefine_CN = {
    Text = "<Title:Transcription automatique>\nLa transcription automatique permet d'effectuer des transcriptions rapidement et en masse.\nPendant la transcription automatique, si un résultat de transcription contient 1 attribut débloqué d'intensité 8, la transcription automatique s'arrête.\nLa transcription automatique peut être effectuée jusqu'à 100 fois.\nLorsque les matériaux sont insuffisants, la transcription s'arrête automatiquement.\n<Title:Passer>\nPendant la transcription automatique, chaque résultat de transcription sera affiché, et vous pouvez choisir de passer le processus de transcription. Après avoir passé, le résultat final de la transcription automatique sera affiché directement."
  },
  LanguageConfig_TrinketAutoSelectTips_CN = {
    Text = "Sélection auto : Prioriser les Pactes de qualité inférieure et de niveau inférieur comme matériaux"
  },
  LanguageConfig_TrinketBatchUnbindComingSoon_CN = {
    Text = "La fonction Tout délier arrive bientôt"
