  LanguageConfig_TrinketBatchUnbindTitle_CN = {
    Text = "Tout délier"
  },
  LanguageConfig_TrinketBindBonusDesc_CN = {
    Text = "Après la liaison, l'attribut principal du Pacte est augmenté de {s1} supplémentaires !"
  },
  LanguageConfig_TrinketBindNoneSelectedTips_CN = {
    Text = "Aucun Pacte disponible à lier. Veuillez en sélectionner au moins un."
  },
  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Lien du Pacte>\nLes Gardiens du secret peuvent désormais lier des Pactes à des Éveilleurs.\nChaque Éveilleur dispose de 6 emplacements de liaison (un Pacte par emplacement).\nUne fois lié, l'attribut principal du Pacte est augmenté de 50 %.\nLes Pactes liés n'apparaîtront pas dans votre Inventaire ni dans le système d'Alchimie.\nSi un Éveilleur n'a aucun Pacte équipé dans un emplacement d'équipe ou de Soutien, son Pacte lié sera automatiquement équipé.\nAméliorer un Pacte lié ne le déliera pas ; ses attributs améliorés se mettront à jour automatiquement.\n\n<Title:Déliaison du Pacte>\nPour modifier ou supprimer un lien, utilisez l'option de déliaison sur l'écran de Liaison du Pacte.\nDélier un seul emplacement coûte 10 Pactes du même type (n'importe quel emplacement peut être utilisé comme coût)."
  },
  LanguageConfig_TrinketBindSuccessTips_CN = {
